#!/usr/bin/env python3
"""Leakage-safe nested mixture-of-experts screen for exact300 R3.

All expert and router declarations are frozen before R3 labels are opened.
For every canonical outer REFNO fold, all 2,172 auxiliary rows belonging to
an outer-test REFNO are excluded.  Expert probabilities used to fit a router
are themselves generated by deterministic, REFNO-isolated inner cross-fitting.
The script never reads prior predictions, prior evaluations, PMAGRESULT, or
row-level ROCKMAG as runtime inputs.
"""

from __future__ import annotations

import argparse
from collections import Counter, defaultdict
from dataclasses import asdict, dataclass
import hashlib
import json
from pathlib import Path
import sys
from typing import Any, Mapping, Sequence

import numpy as np
from sklearn.ensemble import (
    ExtraTreesClassifier,
    HistGradientBoostingClassifier,
    HistGradientBoostingRegressor,
    RandomForestClassifier,
)
from sklearn.linear_model import LogisticRegression
from sklearn.preprocessing import StandardScaler


ROOT = Path(__file__).resolve().parents[1]
SCRIPTS = ROOT / "scripts"
if str(SCRIPTS) not in sys.path:
    sys.path.insert(0, str(SCRIPTS))

import build_r3_exact300_auxiliary_numeric_cache as numeric_builder  # noqa: E402
import build_r3_exact300_component_bridge_cache as component_builder  # noqa: E402
import build_r3_exact300_own_study_cache as own_builder  # noqa: E402
import experiment_r3_exact300_auxiliary_model_sweep as numeric_sweep  # noqa: E402
import experiment_r3_exact300_auxiliary_training as auxiliary  # noqa: E402
import experiment_r3_exact300_component_bridge_auxiliary as component_eval  # noqa: E402
import experiment_r3_exact300_own_study_auxiliary as own_eval  # noqa: E402
import experiment_r3_pdf_only_strategies as base  # noqa: E402


OUTPUT_DIR = ROOT / "tmp/r3_exact_300_resultno_v2/nested_router_v1"
RANDOM_STATE = 35731
INNER_SPLITS = 4
TARGET_ACCURACY = 0.90
STANDARDIZED_CLIP = 12.0


@dataclass(frozen=True)
class ExpertSpec:
    name: str
    matrix: str
    kind: str
    standardized: bool = False


@dataclass(frozen=True)
class RouterSpec:
    name: str
    kind: str
    context: str


def expert_specs() -> tuple[ExpertSpec, ...]:
    """Small heterogeneous expert family, declared without label access."""

    return (
        ExpertSpec("expert_hgb_combined", "combined", "hgb10"),
        ExpertSpec("expert_rf_combined", "combined", "rf8"),
        ExpertSpec("expert_extra_combined", "combined", "extra8"),
        ExpertSpec(
            "expert_logreg_combined", "combined", "logreg001", standardized=True
        ),
        ExpertSpec(
            "expert_hgb_component_all", "combined_plus_component_all", "hgb16"
        ),
        ExpertSpec(
            "expert_rf_component_all", "combined_plus_component_all", "rf8"
        ),
    )


def router_specs() -> tuple[RouterSpec, ...]:
    """Router candidates and fixed fusions, frozen before labels are read."""

    return (
        RouterSpec("fusion_mean_all", "mean", "probability"),
        RouterSpec("fusion_median_all", "median", "probability"),
        RouterSpec("stack_probability_logreg", "stack_logreg", "probability"),
        RouterSpec("stack_context_logreg", "stack_logreg", "full_context"),
        RouterSpec("stack_probability_hgb", "stack_hgb", "probability"),
        RouterSpec("stack_context_hgb", "stack_hgb", "full_context"),
        RouterSpec(
            "router_correctness_logreg_soft",
            "correctness_logreg_soft",
            "full_context",
        ),
        RouterSpec(
            "router_correctness_logreg_hard",
            "correctness_logreg_hard",
            "full_context",
        ),
        RouterSpec("router_loss_hgb_soft", "loss_hgb_soft", "full_context"),
        RouterSpec("router_loss_hgb_hard", "loss_hgb_hard", "full_context"),
    )


def parse_folds(value: str) -> tuple[int, ...]:
    if value.casefold() == "all":
        return tuple(range(1, auxiliary.N_SPLITS + 1))
    try:
        folds = tuple(sorted({int(item.strip()) for item in value.split(",")}))
    except ValueError as exc:
        raise argparse.ArgumentTypeError(
            "folds must be 'all' or comma-separated integers"
        ) from exc
    if not folds or any(fold < 1 or fold > auxiliary.N_SPLITS for fold in folds):
        raise argparse.ArgumentTypeError("folds must be between 1 and 5")
    return folds


def deterministic_group_folds(
    indices: np.ndarray,
    groups: Sequence[str],
    *,
    n_splits: int = INNER_SPLITS,
    seed: int = RANDOM_STATE,
) -> list[tuple[np.ndarray, np.ndarray]]:
    """Assign complete groups to stable, approximately row-balanced folds."""

    index = np.asarray(indices, dtype=np.int64)
    if len(index) != len(groups):
        raise ValueError("indices and groups differ in length")
    members: dict[str, list[int]] = defaultdict(list)
    for row_index, group in zip(index, groups):
        members[str(group)].append(int(row_index))
    if len(members) < n_splits:
        raise ValueError("fewer groups than deterministic inner folds")

    def tie_break(group: str) -> str:
        return hashlib.sha256(f"{seed}:{group}".encode("utf-8")).hexdigest()

    ordered = sorted(members, key=lambda group: (-len(members[group]), tie_break(group)))
    fold_rows: list[list[int]] = [[] for _ in range(n_splits)]
    fold_groups: list[set[str]] = [set() for _ in range(n_splits)]
    for group in ordered:
        target_fold = min(
            range(n_splits),
            key=lambda fold: (len(fold_rows[fold]), len(fold_groups[fold]), fold),
        )
        fold_rows[target_fold].extend(members[group])
        fold_groups[target_fold].add(group)

    all_rows = set(int(value) for value in index)
    output: list[tuple[np.ndarray, np.ndarray]] = []
    for validation_rows in fold_rows:
        validation = np.asarray(sorted(validation_rows), dtype=np.int64)
        validation_set = set(int(value) for value in validation)
        fit = np.asarray(sorted(all_rows - validation_set), dtype=np.int64)
        if not len(validation) or validation_set & set(int(value) for value in fit):
            raise AssertionError("invalid deterministic group split")
        output.append((fit, validation))
    if Counter(int(value) for _, validation in output for value in validation) != Counter(
        int(value) for value in index
    ):
        raise AssertionError("inner folds do not cover every training row once")
    return output


def make_expert(kind: str) -> Any:
    if kind == "hgb10":
        return HistGradientBoostingClassifier(
            max_iter=260,
            learning_rate=0.035,
            max_leaf_nodes=7,
            min_samples_leaf=10,
            l2_regularization=1.0,
            random_state=RANDOM_STATE,
        )
    if kind == "hgb16":
        return HistGradientBoostingClassifier(
            max_iter=240,
            learning_rate=0.04,
            max_leaf_nodes=7,
            min_samples_leaf=16,
            l2_regularization=0.5,
            random_state=RANDOM_STATE,
        )
    if kind == "rf8":
        return RandomForestClassifier(
            n_estimators=600,
            max_features=0.5,
            min_samples_leaf=8,
            n_jobs=-1,
            random_state=RANDOM_STATE,
        )
    if kind == "extra8":
        return ExtraTreesClassifier(
            n_estimators=600,
            max_features=0.5,
            min_samples_leaf=8,
            n_jobs=-1,
            random_state=RANDOM_STATE,
        )
    if kind == "logreg001":
        return LogisticRegression(
            C=0.01,
            solver="liblinear",
            max_iter=2_000,
            random_state=RANDOM_STATE,
        )
    raise ValueError(f"unknown expert kind: {kind}")


@dataclass
class FittedExpert:
    model: Any
    scaler: StandardScaler | None

    def predict(self, matrix: np.ndarray) -> np.ndarray:
        values = np.asarray(matrix, dtype=np.float64)
        if self.scaler is not None:
            values = np.clip(
                self.scaler.transform(values), -STANDARDIZED_CLIP, STANDARDIZED_CLIP
            )
        # NumPy/Accelerate on this runtime spuriously warns for finite matmul;
        # the explicit clipping and postcondition below retain a strict boundary.
        with np.errstate(divide="ignore", over="ignore", invalid="ignore"):
            probability = np.asarray(
                self.model.predict_proba(values)[:, 1], dtype=np.float64
            )
        if probability.ndim != 1 or not np.isfinite(probability).all():
            raise AssertionError("expert produced invalid probabilities")
        return probability


def fit_expert(
    spec: ExpertSpec,
    matrix: np.ndarray,
    train_index: np.ndarray,
    labels: np.ndarray,
    sample_weight: np.ndarray,
) -> FittedExpert:
    train = np.asarray(matrix[train_index], dtype=np.float64)
    scaler = StandardScaler() if spec.standardized else None
    if scaler is not None:
        train = np.clip(
            scaler.fit_transform(train), -STANDARDIZED_CLIP, STANDARDIZED_CLIP
        )
    model = make_expert(spec.kind)
    model.fit(train, labels[train_index], sample_weight=sample_weight)
    return FittedExpert(model=model, scaler=scaler)


def probability_features(probabilities: np.ndarray) -> np.ndarray:
    values = np.asarray(probabilities, dtype=np.float64)
    if values.ndim != 2 or not np.isfinite(values).all():
        raise ValueError("expert probability matrix must be finite and two-dimensional")
    mean = values.mean(axis=1)
    minimum = values.min(axis=1)
    maximum = values.max(axis=1)
    sorted_values = np.sort(values, axis=1)
    vote = (values >= 0.5).mean(axis=1)
    margin = np.abs(values - 0.5)
    summary = np.column_stack(
        (
            mean,
            values.std(axis=1),
            minimum,
            maximum,
            maximum - minimum,
            vote,
            margin.mean(axis=1),
            sorted_values[:, -1] - sorted_values[:, -2],
            sorted_values[:, 1] - sorted_values[:, 0],
        )
    )
    return np.concatenate((values, summary), axis=1)


def meta_matrix(
    expert_probability: np.ndarray,
    own_target: np.ndarray,
    component_bridge: np.ndarray,
    context: str,
) -> np.ndarray:
    probability = probability_features(expert_probability)
    if context == "probability":
        return probability
    if context == "full_context":
        output = np.concatenate(
            (
                probability,
                np.asarray(own_target, dtype=np.float64),
                np.asarray(component_bridge, dtype=np.float64),
            ),
            axis=1,
        )
        if not np.isfinite(output).all():
            raise ValueError("router context contains non-finite values")
        return output
    raise ValueError(f"unknown router context: {context}")


def fit_binary_logreg(
    train: np.ndarray,
    labels: np.ndarray,
    weights: np.ndarray,
    *,
    balanced: bool = False,
) -> tuple[Any, StandardScaler | None]:
    unique = np.unique(labels)
    if len(unique) == 1:
        return float(unique[0]), None
    scaler = StandardScaler()
    transformed = np.clip(
        scaler.fit_transform(train), -STANDARDIZED_CLIP, STANDARDIZED_CLIP
    )
    model = LogisticRegression(
        C=0.1,
        solver="liblinear",
        max_iter=2_000,
        class_weight="balanced" if balanced else None,
        random_state=RANDOM_STATE,
    )
    model.fit(transformed, labels, sample_weight=weights)
    return model, scaler


def predict_binary_logreg(
    fitted: tuple[Any, StandardScaler | None], test: np.ndarray
) -> np.ndarray:
    model, scaler = fitted
    if scaler is None:
        return np.full(len(test), float(model), dtype=np.float64)
    transformed = np.clip(
        scaler.transform(test), -STANDARDIZED_CLIP, STANDARDIZED_CLIP
    )
    with np.errstate(divide="ignore", over="ignore", invalid="ignore"):
        probability = np.asarray(
            model.predict_proba(transformed)[:, 1], dtype=np.float64
        )
    if not np.isfinite(probability).all():
        raise AssertionError("linear router produced non-finite probabilities")
    return probability


def fit_predict_router(
    spec: RouterSpec,
    train_probability: np.ndarray,
    test_probability: np.ndarray,
    train_own_target: np.ndarray,
    test_own_target: np.ndarray,
    train_component_bridge: np.ndarray,
    test_component_bridge: np.ndarray,
    train_labels: np.ndarray,
    train_weight: np.ndarray,
) -> np.ndarray:
    if spec.kind == "mean":
        return test_probability.mean(axis=1)
    if spec.kind == "median":
        return np.median(test_probability, axis=1)

    train = meta_matrix(
        train_probability, train_own_target, train_component_bridge, spec.context
    )
    test = meta_matrix(
        test_probability, test_own_target, test_component_bridge, spec.context
    )
    if spec.kind == "stack_logreg":
        fitted = fit_binary_logreg(train, train_labels, train_weight)
        return predict_binary_logreg(fitted, test)
    if spec.kind == "stack_hgb":
        model = HistGradientBoostingClassifier(
            max_iter=180,
            learning_rate=0.035,
            max_leaf_nodes=5,
            min_samples_leaf=25,
            l2_regularization=2.0,
            random_state=RANDOM_STATE,
        )
        model.fit(train, train_labels, sample_weight=train_weight)
        return np.asarray(model.predict_proba(test)[:, 1], dtype=np.float64)

    if spec.kind.startswith("correctness_logreg_"):
        qualities = []
        decisions = train_probability >= 0.5
        for column in range(train_probability.shape[1]):
            correct = (decisions[:, column] == train_labels).astype(np.int8)
            fitted = fit_binary_logreg(
                train, correct, train_weight, balanced=True
            )
            qualities.append(predict_binary_logreg(fitted, test))
        quality = np.column_stack(qualities)
        if spec.kind.endswith("_hard"):
            selected = quality.argmax(axis=1)
            return test_probability[np.arange(len(test_probability)), selected]
        denominator = np.maximum(quality.sum(axis=1), 1e-12)
        return (quality * test_probability).sum(axis=1) / denominator

    if spec.kind.startswith("loss_hgb_"):
        predicted_losses = []
        for column in range(train_probability.shape[1]):
            loss = (train_probability[:, column] - train_labels) ** 2
            model = HistGradientBoostingRegressor(
                loss="squared_error",
                max_iter=140,
                learning_rate=0.04,
                max_leaf_nodes=5,
                min_samples_leaf=30,
                l2_regularization=2.0,
                random_state=RANDOM_STATE + column,
            )
            model.fit(train, loss, sample_weight=train_weight)
            predicted_losses.append(np.maximum(model.predict(test), 0.0))
        loss_matrix = np.column_stack(predicted_losses)
        if spec.kind.endswith("_hard"):
            selected = loss_matrix.argmin(axis=1)
            return test_probability[np.arange(len(test_probability)), selected]
        logits = -loss_matrix / 0.10
        logits -= logits.max(axis=1, keepdims=True)
        quality = np.exp(logits)
        quality /= quality.sum(axis=1, keepdims=True)
        return (quality * test_probability).sum(axis=1)
    raise ValueError(f"unknown router kind: {spec.kind}")


def transition_record(
    labels: np.ndarray, control_probability: np.ndarray, candidate_probability: np.ndarray
) -> dict[str, int]:
    control_error = (control_probability >= 0.5) != labels
    candidate_error = (candidate_probability >= 0.5) != labels
    return {
        "control_errors": int(control_error.sum()),
        "candidate_errors": int(candidate_error.sum()),
        "errors_resolved": int((control_error & ~candidate_error).sum()),
        "errors_introduced": int((~control_error & candidate_error).sum()),
    }


def write_probabilities(path: Path, probabilities: Mapping[str, np.ndarray]) -> None:
    arrays = {
        name: np.asarray(value, dtype=np.float32)
        for name, value in sorted(probabilities.items())
    }
    if any(
        value.shape != (auxiliary.EXPECTED_EXACT_ROWS,)
        or not np.isfinite(value).all()
        for value in arrays.values()
    ):
        raise ValueError("full router OOF requires 300 finite rows per candidate")
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(path.name + ".tmp")
    with temporary.open("wb") as handle:
        np.savez_compressed(handle, **arrays)
    temporary.replace(path)


def main(argv: Sequence[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--numeric-cache", type=Path, default=numeric_builder.DEFAULT_CACHE)
    parser.add_argument(
        "--numeric-manifest", type=Path, default=numeric_builder.DEFAULT_MANIFEST
    )
    parser.add_argument("--own-cache", type=Path, default=own_builder.DEFAULT_CACHE)
    parser.add_argument("--own-manifest", type=Path, default=own_builder.DEFAULT_MANIFEST)
    parser.add_argument(
        "--component-cache", type=Path, default=component_builder.DEFAULT_CACHE
    )
    parser.add_argument(
        "--component-manifest", type=Path, default=component_builder.DEFAULT_MANIFEST
    )
    parser.add_argument("--exact-identity", type=Path, default=auxiliary.EXACT_IDENTITY)
    parser.add_argument("--full-identity", type=Path, default=auxiliary.FULL_IDENTITY)
    parser.add_argument("--fold-manifest", type=Path, default=auxiliary.FOLD_MANIFEST)
    parser.add_argument("--targets", type=Path, default=base.DEFAULT_TARGETS)
    parser.add_argument("--pdf-dir", type=Path, default=base.DEFAULT_PDF_DIR)
    parser.add_argument("--folds", type=parse_folds, default=(1, 2, 3))
    parser.add_argument("--output-dir", type=Path, default=OUTPUT_DIR)
    args = parser.parse_args(argv)

    paths = {
        "numeric_cache": args.numeric_cache.resolve(),
        "numeric_manifest": args.numeric_manifest.resolve(),
        "own_cache": args.own_cache.resolve(),
        "own_manifest": args.own_manifest.resolve(),
        "component_cache": args.component_cache.resolve(),
        "component_manifest": args.component_manifest.resolve(),
        "exact_identity": args.exact_identity.resolve(),
        "full_identity": args.full_identity.resolve(),
        "fold_manifest": args.fold_manifest.resolve(),
        "targets": args.targets.resolve(),
        "pdf_dir": args.pdf_dir.resolve(),
    }
    output_dir = args.output_dir.resolve()
    output_dir.mkdir(parents=True, exist_ok=True)

    if base.file_sha256(paths["exact_identity"]) != auxiliary.EXACT_IDENTITY_SHA256:
        raise ValueError("exact300 identity hash mismatch")
    if base.file_sha256(paths["full_identity"]) != auxiliary.FULL_IDENTITY_SHA256:
        raise ValueError("full identity hash mismatch")
    if base.file_sha256(paths["fold_manifest"]) != auxiliary.FOLD_MANIFEST_SHA256:
        raise ValueError("canonical fold manifest hash mismatch")
    if base.file_sha256(paths["targets"]) != auxiliary.TARGETS_SHA256:
        raise ValueError("targets workbook hash mismatch")

    full_records, full_coverage = base.load_pdf_only_identity(
        paths["full_identity"], paths["pdf_dir"]
    )
    exact_records, exact_coverage = base.load_pdf_only_identity(
        paths["exact_identity"], paths["pdf_dir"]
    )
    full_lookup = auxiliary.validate_membership(full_records, exact_records)
    fold_ids = auxiliary.load_fold_manifest(paths["fold_manifest"], exact_records)
    full_alignment = auxiliary.sha256_records(full_records)

    numeric_arrays, numeric_manifest = numeric_sweep.validate_cache(
        paths["numeric_cache"], paths["numeric_manifest"]
    )
    own_arrays, own_manifest = own_eval.validate_own_cache(
        paths["own_cache"], paths["own_manifest"], len(full_records), full_alignment
    )
    component_arrays, component_manifest = component_eval.validate_component_cache(
        paths["component_cache"],
        paths["component_manifest"],
        len(full_records),
        full_alignment,
    )
    if numeric_manifest.get("scope", {}).get("full_alignment_sha256") != full_alignment:
        raise ValueError("numeric cache alignment differs from full identity")
    matrices = {**numeric_arrays, **own_arrays, **component_arrays}
    experts = expert_specs()
    routers = router_specs()
    if any(spec.matrix not in matrices for spec in experts):
        raise ValueError("an expert matrix is absent from the frozen caches")
    if len({spec.name for spec in experts}) != len(experts) or len(
        {spec.name for spec in routers}
    ) != len(routers):
        raise ValueError("duplicate expert or router declaration")

    # The complete candidate receipt is committed before the first R3 label read.
    freeze = {
        "schema_version": "r3_exact300_nested_router_candidate_freeze_v1",
        "status": "FROZEN_BEFORE_LABEL_ACCESS",
        "evaluated_folds": list(args.folds),
        "inner_split": {
            "method": "deterministic greedy row-balanced REFNO assignment",
            "n_splits": INNER_SPLITS,
            "seed": RANDOM_STATE,
        },
        "experts": [asdict(spec) for spec in experts],
        "routers": [asdict(spec) for spec in routers],
        "decision_threshold": 0.5,
        "label_free_numeric_stability": {
            "standardized_feature_clip": [
                -STANDARDIZED_CLIP,
                STANDARDIZED_CLIP,
            ],
            "finite_probability_postcondition": True,
        },
        "continuation_gate": (
            "best router must strictly exceed the strongest single expert on the "
            "same staged folds"
        ),
        "inputs": {
            name: {"path": str(path), "sha256": base.file_sha256(path)}
            for name, path in paths.items()
            if name != "pdf_dir"
        },
        "runtime_boundary": {
            "labels_read_at_freeze": False,
            "pmagresult_or_row_rockmag_used_as_feature": False,
            "prior_oof_or_evaluation_read": False,
            "identifiers_used_as_predictive_features": False,
            "refno_used_only_for_group_isolation": True,
        },
        "script": {
            "path": str(Path(__file__).resolve()),
            "sha256": base.file_sha256(Path(__file__).resolve()),
        },
    }
    full_run = args.folds == tuple(range(1, auxiliary.N_SPLITS + 1))
    freeze_path = output_dir / (
        "candidate_freeze.json"
        if full_run
        else "candidate_freeze_folds_" + "_".join(map(str, args.folds)) + ".json"
    )
    base.atomic_json(freeze_path, freeze)

    labels_by_resultno = base.load_training_labels(
        paths["targets"], {record["RESULTNO"] for record in full_records}
    )
    full_labels = np.asarray(
        [labels_by_resultno[record["RESULTNO"]] for record in full_records],
        dtype=np.int8,
    )
    exact_labels = np.asarray(
        [labels_by_resultno[record["RESULTNO"]] for record in exact_records],
        dtype=np.int8,
    )

    all_names = [spec.name for spec in experts] + [spec.name for spec in routers]
    probabilities = {
        name: np.full(auxiliary.EXPECTED_EXACT_ROWS, np.nan, dtype=np.float64)
        for name in all_names
    }
    canonical_targets = [
        base.canonical_target_identity(record["ROCKNAME"]) for record in full_records
    ]
    outer_audit: list[dict[str, Any]] = []
    for fold in args.folds:
        exact_test = np.flatnonzero(fold_ids == fold)
        outer_train, outer_test, outer_test_refnos = auxiliary.auxiliary_split(
            full_records, exact_records, exact_test, full_lookup
        )
        outer_train_refnos = {
            full_records[int(index)]["REFNO"] for index in outer_train
        }
        groups = [full_records[int(index)]["REFNO"] for index in outer_train]
        inner_folds = deterministic_group_folds(outer_train, groups)
        inner_probability = np.full(
            (len(full_records), len(experts)), np.nan, dtype=np.float64
        )
        inner_audit: list[dict[str, Any]] = []
        for inner_fold, (inner_fit, inner_validation) in enumerate(inner_folds, start=1):
            fit_refnos = {full_records[int(index)]["REFNO"] for index in inner_fit}
            validation_refnos = {
                full_records[int(index)]["REFNO"] for index in inner_validation
            }
            if fit_refnos & validation_refnos:
                raise AssertionError("inner fit/validation REFNO overlap")
            if (fit_refnos | validation_refnos) & outer_test_refnos:
                raise AssertionError("outer-test REFNO entered inner cross-fitting")
            inner_weight = base.inverse_target_multiplicity_weights(
                inner_fit, full_records, canonical_targets
            )
            for column, spec in enumerate(experts):
                fitted = fit_expert(
                    spec,
                    matrices[spec.matrix],
                    inner_fit,
                    full_labels,
                    inner_weight,
                )
                inner_probability[inner_validation, column] = fitted.predict(
                    matrices[spec.matrix][inner_validation]
                )
            inner_audit.append(
                {
                    "inner_fold": inner_fold,
                    "fit_rows": int(len(inner_fit)),
                    "fit_papers": len(fit_refnos),
                    "validation_rows": int(len(inner_validation)),
                    "validation_papers": len(validation_refnos),
                    "fit_validation_refno_overlap": 0,
                    "outer_test_refno_overlap": 0,
                }
            )

        train_probability = inner_probability[outer_train]
        if not np.isfinite(train_probability).all():
            raise AssertionError("inner cross-fitted expert probabilities are incomplete")
        outer_weight = base.inverse_target_multiplicity_weights(
            outer_train, full_records, canonical_targets
        )
        test_probability = np.zeros((len(outer_test), len(experts)), dtype=np.float64)
        for column, spec in enumerate(experts):
            fitted = fit_expert(
                spec,
                matrices[spec.matrix],
                outer_train,
                full_labels,
                outer_weight,
            )
            values = fitted.predict(matrices[spec.matrix][outer_test])
            test_probability[:, column] = values
            probabilities[spec.name][exact_test] = values

        for spec in routers:
            values = fit_predict_router(
                spec,
                train_probability,
                test_probability,
                own_arrays["own_target"][outer_train],
                own_arrays["own_target"][outer_test],
                component_arrays["component_bridge"][outer_train],
                component_arrays["component_bridge"][outer_test],
                full_labels[outer_train],
                outer_weight,
            )
            if values.shape != (len(outer_test),) or not np.isfinite(values).all():
                raise AssertionError(f"router produced invalid probabilities: {spec.name}")
            probabilities[spec.name][exact_test] = np.clip(values, 0.0, 1.0)

        excluded_rows = sum(
            record["REFNO"] in outer_test_refnos for record in full_records
        )
        outer_audit.append(
            {
                "fold": fold,
                "test_rows": int(len(exact_test)),
                "test_papers": len(outer_test_refnos),
                "auxiliary_train_rows": int(len(outer_train)),
                "auxiliary_train_papers": len(outer_train_refnos),
                "excluded_full_rows": int(excluded_rows),
                "all_outer_test_refno_rows_excluded": True,
                "train_test_refno_overlap": len(
                    outer_train_refnos & outer_test_refnos
                ),
                "inner_cross_fitting": inner_audit,
            }
        )
        print(
            f"fold {fold}: train_rows={len(outer_train)}, test_rows={len(exact_test)}, "
            f"experts={len(experts)}, routers={len(routers)}",
            flush=True,
        )

    covered = np.isin(fold_ids, np.asarray(args.folds, dtype=np.int8))
    results: dict[str, Any] = {}
    for name in all_names:
        values = probabilities[name]
        if not np.isfinite(values[covered]).all():
            raise AssertionError(f"candidate is incomplete on requested folds: {name}")
        results[name] = {
            "role": "expert_control" if name.startswith("expert_") else "router",
            "aggregate": base.metric_record(exact_labels[covered], values[covered]),
            "folds": [
                {
                    "fold": fold,
                    **base.metric_record(
                        exact_labels[fold_ids == fold], values[fold_ids == fold]
                    ),
                }
                for fold in args.folds
            ],
        }

    expert_names = [spec.name for spec in experts]
    router_names = [spec.name for spec in routers]
    rank_key = lambda name: (  # noqa: E731
        results[name]["aggregate"]["accuracy"],
        results[name]["aggregate"]["macro_f1"],
        results[name]["aggregate"]["balanced_accuracy"],
    )
    best_expert = max(expert_names, key=rank_key)
    best_router = max(router_names, key=rank_key)
    ranking = sorted(all_names, key=rank_key, reverse=True)
    for name in all_names:
        results[name]["transition_vs_best_single_expert"] = transition_record(
            exact_labels[covered],
            probabilities[best_expert][covered],
            probabilities[name][covered],
        )

    expert_accuracy = float(results[best_expert]["aggregate"]["accuracy"])
    router_accuracy = float(results[best_router]["aggregate"]["accuracy"])
    strict_improvement = router_accuracy > expert_accuracy
    oof_record = None
    if full_run:
        oof_path = output_dir / "oof_probabilities.npz"
        write_probabilities(oof_path, probabilities)
        oof_record = {"path": str(oof_path), "sha256": base.file_sha256(oof_path)}

    report = {
        "schema_version": "r3_exact300_nested_router_grouped_oof_v1",
        "status": "complete",
        "mode": "full_five_fold" if full_run else "staged_screen",
        "scope": {
            "evaluated_folds": list(args.folds),
            "evaluated_rows": int(covered.sum()),
            "full_coverage": full_run,
            "exact_membership": exact_coverage,
            "auxiliary_candidate_pool": full_coverage,
        },
        "compliance_audit": {
            "canonical_outer_fold_manifest_sha256": auxiliary.FOLD_MANIFEST_SHA256,
            "candidate_receipt_written_before_label_access": True,
            "feature_caches_frozen_without_labels": True,
            "inner_expert_probabilities_cross_fitted_by_refno": True,
            "all_outer_test_refno_rows_excluded_from_every_fit": True,
            "all_inner_validation_refno_rows_excluded_from_inner_expert_fit": True,
            "pmagresult_or_row_rockmag_used_as_feature": False,
            "prior_oof_or_evaluation_read": False,
            "identifiers_used_as_predictive_features": False,
            "fixed_decision_threshold": 0.5,
        },
        "inputs": freeze["inputs"],
        "candidate_freeze": {
            "path": str(freeze_path),
            "sha256": base.file_sha256(freeze_path),
        },
        "feature_summary": {
            "numeric_matrices": numeric_manifest.get("matrices"),
            "own_matrices": own_manifest.get("matrices"),
            "component_matrices": component_manifest.get("matrices"),
            "router_context_dimensions": {
                "expert_probabilities": len(experts),
                "probability_summary": 9,
                "own_target": int(own_arrays["own_target"].shape[1]),
                "component_bridge": int(
                    component_arrays["component_bridge"].shape[1]
                ),
            },
        },
        "outer_fold_audit": outer_audit,
        "ranking": ranking,
        "best_single_expert": {"strategy": best_expert, **results[best_expert]},
        "best_router": {"strategy": best_router, **results[best_router]},
        "models": results,
        "continuation_gate": {
            "rule": "strictly exceed strongest single expert on the same folds",
            "best_single_expert": best_expert,
            "single_expert_accuracy": expert_accuracy,
            "best_router": best_router,
            "router_accuracy": router_accuracy,
            "strict_improvement": strict_improvement,
            "continue_to_full_five_folds": bool(not full_run and strict_improvement),
        },
        "promotion_gate": {
            "target_accuracy": TARGET_ACCURACY,
            "full_coverage_required": True,
            "passed": bool(full_run and router_accuracy >= TARGET_ACCURACY),
            "decision": (
                "EXACT300_TARGET_REACHED"
                if full_run and router_accuracy >= TARGET_ACCURACY
                else "STAGED_SCREEN_ONLY"
                if not full_run
                else "EXACT300_TARGET_NOT_REACHED"
            ),
        },
        "artifacts": {
            "oof_probabilities": oof_record,
            "script": {
                "path": str(Path(__file__).resolve()),
                "sha256": base.file_sha256(Path(__file__).resolve()),
            },
        },
    }
    report_path = output_dir / (
        "report.json"
        if full_run
        else "folds_" + "_".join(map(str, args.folds)) + "_report.json"
    )
    base.atomic_json(report_path, report)
    print(
        json.dumps(
            {
                "report": str(report_path),
                "best_single_expert": report["best_single_expert"],
                "best_router": report["best_router"],
                "continuation_gate": report["continuation_gate"],
                "promotion_gate": report["promotion_gate"],
            },
            ensure_ascii=False,
            indent=2,
        ),
        flush=True,
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
